import weakref
import gc

class Finalizer:
    def __init__(self, ws):
        self.ws = ws
    def __del__(self):
        # This is called when Finalizer is GC'd.
        # But we want to check if some other object is in the weakset.
        pass

# Use a custom class to simulate the async generator and the finalizer hook.
class MockAgen:
    def __init__(self):
        self.finalizer_callback = None
    def __del__(self):
        if self.finalizer_callback:
            self.finalizer_callback(self)

ws = weakref.WeakSet()
agen = MockAgen()
ws.add(agen)

def my_finalizer(a):
    print(f'In finalizer: {a in ws}')

agen.finalizer_callback = my_finalizer
del agen
gc.collect()
